export declare const notFound404CSS = ".not-found-container {\n  min-height: 100vh;\n  background: linear-gradient(to bottom, #0f172a, #1e293b);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 1rem;\n}\n\n.not-found-content {\n  max-width: 42rem;\n  width: 100%;\n  text-align: center;\n}\n\n.not-found-animation {\n  margin-bottom: 2rem;\n  max-width: 36rem;\n  margin-left: auto;\n  margin-right: auto;\n}\n\n.not-found-title {\n  font-size: 3.75rem;\n  font-weight: bold;\n  color: #ffffff;\n  margin-bottom: 1rem;\n}\n\n.not-found-subtitle {\n  font-size: 1.5rem;\n  font-weight: 600;\n  color: #d1d5db;\n  margin-bottom: 1rem;\n}\n\n.not-found-text {\n  color: #9ca3af;\n  margin-bottom: 2rem;\n  max-width: 28rem;\n  margin-left: auto;\n  margin-right: auto;\n}\n\n.not-found-button {\n  display: inline-block;\n  background-color: #ffffff;\n  color: #0f172a;\n  padding: 0.75rem 2rem;\n  border-radius: 0.5rem;\n  font-weight: 600;\n  text-decoration: none;\n  transition: background-color 0.2s;\n}\n\n.not-found-button:hover {\n  background-color: #f3f4f6;\n}\n";
